import os,re,json
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]

from collections import Counter
def transform(grid):
    h,w=len(grid),len(grid[0])
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    # divider: full row/col of a single non-background color
    drows=[i for i in range(h) if len(set(grid[i]))==1 and grid[i][0]!=bg]
    dcols=[j for j in range(w) if len({grid[i][j] for i in range(h)})==1 and grid[0][j]!=bg]
    rseg=[]; s=0
    for i in drows+[h]:
        if i>s: rseg.append((s,i))
        s=i+1
    cseg=[]; s=0
    for j in dcols+[w]:
        if j>s: cseg.append((s,j))
        s=j+1
    # find content cell: cell with fewest bg cells
    def cell(rs,cs):
        return [row[cs[0]:cs[1]] for row in grid[rs[0]:rs[1]]]
    cells=[(rs,cs) for rs in rseg for cs in cseg]
    content=min(cells,key=lambda c: sum(v==bg for row in cell(*c) for v in row))
    C=cell(*content)
    out=[row[:] for row in grid]
    for rs,cs in cells:
        for i in range(rs[1]-rs[0]):
            for j in range(cs[1]-cs[0]):
                out[rs[0]+i][cs[0]+j]=C[i%len(C)][j%len(C)]
    return out

